add_action( 'woocommerce_before_cart', 'perfectpixel_debug_cart_contents' );

function perfectpixel_debug_cart_contents() {
	if ( empty( $_GET['perfectpixel_debug_cart'] ) || ! current_user_can( 'manage_woocommerce' ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		return;
	}
	$items = array();
	foreach ( WC()->cart->get_cart() as $key => $item ) {
		$copy         = $item;
		$copy['data'] = $item['data'] ? sprintf( '%s #%d (%s)', get_class( $item['data'] ), $item['data']->get_id(), $item['data']->get_name() ) : null;
		$items[ $key ] = $copy;
	}
	$dump = array(
		'items'   => $items,
		'totals'  => WC()->cart->get_totals(),
		'coupons' => WC()->cart->get_applied_coupons(),
	);
	echo '<pre style="max-height:400px;overflow:auto;font-size:12px;background:#f6f7f7;padding:1em">' . esc_html( print_r( $dump, true ) ) . '</pre>'; // phpcs:ignore WordPress.PHP.DevelopmentFunctions
}
